std::complex<double> F1anom(double s12, double s45, double mt2, double musq) {

  std::complex<double> F1anom;

  if (mt2  == zero) {
    F1anom = one/two/(s45-s12) * (1.0 + s45/(s45-s12) * lnrat(-s12, -s45));
    return F1anom;
  } else {
    F1anom = one/two/(s45-s12) 
    * (one + two*mt2*loopI3(s12, 0.0, s45, mt2, mt2, mt2, musq, 0) 
    + (s45/(s45-s12)) 
    * (loopI2(s45, mt2, mt2, musq, 0) - loopI2(s12, mt2, mt2, musq, 0)));
  }

  return F1anom;
}

